def expand_env_var_in_values(d: t.MutableMapping[str, t.Any]) -> None:
    for k, v in d.items():
        if isinstance(v, t.MutableMapping):
            expand_env_var_in_values(v)
        elif isinstance(v, str):
            d[k] = expand_env_var(v)
        elif isinstance(v, t.Sequence):
            d[k] = [expand_env_var(i) for i in v]

def flatten_dict(
    d: t.MutableMapping[str, t.Any],
    parent: str = "",
    sep: str = ".",
) -> t.Generator[tuple[str, t.Any], None, None]:
    """Flatten nested dictionary into a single level dictionary."""
    for k, v in d.items():
        k = f'"{k}"' if any(i in punctuation for i in k) else k
        nkey = parent + sep + k if parent else k
        if isinstance(v, t.MutableMapping):
            yield from flatten_dict(
                t.cast(t.MutableMapping[str, t.Any], v), parent=nkey, sep=sep
            )
        else:
            yield nkey, v

def get_default_config(version: int) -> dict[str, t.Any]:
    config = load_config_file(
        os.path.join(
            os.path.dirname(__file__), f"v{version}", "default_configuration.yaml"
        )
    )
    mod = import_configuration_spec(version)
    assert hasattr(mod, "SCHEMA"), (
        "version %d does not have a validation schema" % version
    )
    try:
        mod.SCHEMA.validate(config)
    except s.SchemaError as e:
        raise BentoMLConfigException(
            "Default configuration for version %d does not conform to given schema:\n%s"
            % (version, e)
        ) from None
    return config

def load_config_file(path: str) -> dict[str, t.Any]:
    """Load configuration from given path."""
    if not os.path.exists(path):
        raise BentoMLConfigException(
            "Configuration file %s not found." % path
        ) from None
    with open(path, "rb") as f:
        config = yaml.safe_load(f)
    return config

class BentoMLConfiguration:
    def __init__(
        self,
        override_config_file: str | None = None,
        override_config_values: str | None = None,
        *,
        validate_schema: bool = True,
        use_version: int = 1,
    ):
        # Load default configuration with latest version.
        self.config = get_default_config(version=use_version)
        spec_module = import_configuration_spec(version=use_version)

        # User override configuration
        if override_config_file is not None:
            logger.info(
                "Applying user config override from path: %s" % override_config_file
            )
            override = load_config_file(override_config_file)
            if "version" not in override:
                # If users does not define a version, we then by default assume they are using v1
                # and we will migrate it to latest version
                logger.debug(
                    "User config does not define a version, assuming given config is version %d..."
                    % use_version
                )
                current = use_version
            else:
                current = override["version"]
            migration = getattr(import_configuration_spec(current), "migration", None)
            # Running migration layer if it exists
            if migration is not None:
                override = migration(override_config=dict(flatten_dict(override)))
            config_merger.merge(self.config, override)

        if override_config_values is not None:
            logger.info(
                "Applying user config override from ENV VAR: %s", override_config_values
            )
            lines = split_with_quotes(
                override_config_values,
                sep=r"\s+",
                quote='"',
                use_regex=True,
            )
            override_config_map = {
                k: yaml.safe_load(v)
                for k, v in [
                    split_with_quotes(line, sep="=", quote='"')
                    for line in lines
                    if line.strip()
                ]
            }
            # Note that this values will only support latest version of configuration,
            # as there is no way for us to infer what values user can pass in.
            # however, if users pass in a version inside this value, we will that to migrate up
            # if possible
            override_version = override_config_map.get("version", use_version)
            logger.debug(
                "Found defined 'version=%d' in BENTOML_CONFIG_OPTIONS."
                % override_version
            )
            migration = getattr(
                import_configuration_spec(override_version), "migration", None
            )
            # Running migration layer if it exists
            if migration is not None:
                override_config_map = migration(override_config=override_config_map)
            # Previous behaviour, before configuration versioning.
            try:
                override = unflatten(override_config_map)
            except ValueError as e:
                raise BentoMLConfigException(
                    f"Failed to parse config options from the env var:\n{e}.\n*** Note: You can use '\"' to quote the key if it contains special characters. ***"
                ) from None
            config_merger.merge(self.config, override)

        if override_config_file is not None or override_config_values is not None:
            self._finalize()

        if validate_schema:
            try:
                spec_module.SCHEMA.validate(self.config)
            except s.SchemaError as e:
                raise BentoMLConfigException(
                    f"Invalid configuration file was given:\n{e}"
                ) from None

    def _finalize(self):
        RUNNER_CFG_KEYS = [
            "batching",
            "resources",
            "logging",
            "metrics",
            "traffic",
            "workers_per_resource",
        ]
        global_runner_cfg = {k: self.config["runners"][k] for k in RUNNER_CFG_KEYS}
        custom_runners_cfg = dict(
            filter(
                lambda kv: kv[0] not in RUNNER_CFG_KEYS,
                self.config["runners"].items(),
            )
        )
        if custom_runners_cfg:
            for runner_name, runner_cfg in custom_runners_cfg.items():
                # key is a runner name
                if runner_cfg.get("resources") == "system":
                    runner_cfg["resources"] = system_resources()
                self.config["runners"][runner_name] = config_merger.merge(
                    deepcopy(global_runner_cfg),
                    runner_cfg,
                )
        expand_env_var_in_values(self.config)

    def to_dict(self) -> providers.ConfigDictType:
        return t.cast(providers.ConfigDictType, self.config)

def reserve_free_port(
    host: str = "localhost",
    port: int | None = None,
    prefix: t.Optional[str] = None,
    max_retry: int = 50,
    enable_so_reuseport: bool = False,
) -> t.Iterator[int]:
    """
    detect free port and reserve until exit the context
    """
    import psutil

    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    if enable_so_reuseport:
        if psutil.WINDOWS:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        elif psutil.MACOS or psutil.FREEBSD:
            sock.setsockopt(socket.SOL_SOCKET, 0x10000, 1)  # SO_REUSEPORT_LB
        else:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)

            if sock.getsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT) == 0:
                raise RuntimeError("Failed to set SO_REUSEPORT.") from None
    if prefix is not None:
        prefix_num = int(prefix) * 10 ** (5 - len(prefix))
        suffix_range = min(65535 - prefix_num, 10 ** (5 - len(prefix)))
        for _ in range(max_retry):
            suffix = random.randint(0, suffix_range)
            port = int(f"{prefix_num + suffix}")
            try:
                sock.bind((host, port))
                break
            except OSError:
                continue
        else:
            raise RuntimeError(
                f"Cannot find free port with prefix {prefix} after {max_retry} retries."
            ) from None
    else:
        if port:
            sock.bind((host, port))
        else:
            sock.bind((host, 0))
    try:
        yield sock.getsockname()[1]
    finally:
        sock.close()

def validate_or_create_dir(*path: PathType) -> None:
    for p in path:
        path_obj = Path(p)

        if path_obj.exists():
            if not path_obj.is_dir():
                raise OSError(20, f"{path_obj} is not a directory")
        else:
            path_obj.mkdir(parents=True)

class AsyncHTTPClient(AsyncClient):
    @cached_property
    def client(self) -> httpx.AsyncClient:
        return httpx.AsyncClient(base_url=self.server_url, timeout=300)

    @staticmethod
    async def wait_until_server_ready(
        host: str,
        port: int,
        timeout: float = 30,
        check_interval: int = 1,
        # set kwargs here to omit gRPC kwargs
        **kwargs: t.Any,
    ) -> None:
        host = host if "://" in host else "http://" + host
        start_time = time.time()

        logger.debug("Waiting for host %s to be ready.", f"{host}:{port}")
        while time.time() - start_time < timeout:
            try:
                async with httpx.AsyncClient(base_url=f"{host}:{port}") as session:
                    resp = await session.get("/readyz")
                    if resp.status_code == 200:
                        break
                    else:
                        await asyncio.sleep(check_interval)
            except (
                httpx.TimeoutException,
                httpx.NetworkError,
                httpx.HTTPStatusError,
            ):
                logger.debug("Server is not ready. Retrying...")
                await asyncio.sleep(check_interval)

        # try to connect one more time and raise exception.
        try:
            async with httpx.AsyncClient(base_url=f"{host}:{port}") as session:
                resp = await session.get("/readyz")
                if resp.status_code != 200:
                    raise TimeoutError(
                        f"Timed out waiting {timeout} seconds for server at '{host}:{port}' to be ready."
                    )
        except (
            httpx.TimeoutException,
            httpx.NetworkError,
            httpx.HTTPStatusError,
        ) as err:
            logger.error("Timed out while connecting to %s:%s:", host, port)
            logger.error(err)
            raise

    async def health(self) -> httpx.Response:
        return await self.client.get("/readyz")

    @classmethod
    async def from_url(cls, server_url: str, **kwargs: t.Any) -> AsyncHTTPClient:
        server_url = server_url if "://" in server_url else "http://" + server_url

        async with httpx.AsyncClient(base_url=server_url) as session:
            resp = await session.get("/docs.json")
            if resp.status_code != 200:
                raise RemoteException(
                    f"Failed to get OpenAPI schema from the server: {resp.status_code} {resp.reason_phrase}:\n{await resp.aread()}"
                )
            openapi_spec = json.loads(await resp.aread())

        dummy_service = Service(openapi_spec["info"]["title"])

        for route, spec in openapi_spec["paths"].items():
            for meth_spec in spec.values():
                if "tags" in meth_spec and "Service APIs" in meth_spec["tags"]:
                    if "x-bentoml-io-descriptor" not in meth_spec["requestBody"]:
                        # TODO: better message stating min version for from_url to work
                        raise BentoMLException(
                            f"Malformed BentoML spec received from BentoML server {server_url}"
                        )
                    if "x-bentoml-io-descriptor" not in meth_spec["responses"]["200"]:
                        raise BentoMLException(
                            f"Malformed BentoML spec received from BentoML server {server_url}"
                        )
                    if "x-bentoml-name" not in meth_spec:
                        raise BentoMLException(
                            f"Malformed BentoML spec received from BentoML server {server_url}"
                        )
                    try:
                        api = InferenceAPI[t.Any](
                            None,
                            io.from_spec(
                                meth_spec["requestBody"]["x-bentoml-io-descriptor"]
                            ),
                            io.from_spec(
                                meth_spec["responses"]["200"]["x-bentoml-io-descriptor"]
                            ),
                            name=meth_spec["x-bentoml-name"],
                            doc=meth_spec["description"],
                            route=route.lstrip("/"),
                        )
                        dummy_service.apis[meth_spec["x-bentoml-name"]] = api
                    except BentoMLException as e:
                        logger.error(
                            "Failed to instantiate client for API %s: ",
                            meth_spec["x-bentoml-name"],
                            e,
                        )

        return cls(dummy_service, server_url)

    async def _call(
        self, inp: t.Any = None, *, _bentoml_api: InferenceAPI[t.Any], **kwargs: t.Any
    ) -> t.Any:
        # All gRPC kwargs should be poped out.
        kwargs = {k: v for k, v in kwargs.items() if not k.startswith("_grpc_")}
        api = _bentoml_api

        if api.multi_input:
            if inp is not None:
                raise BentoMLException(
                    f"'{api.name}' takes multiple inputs; all inputs must be passed as keyword arguments."
                )
            fake_resp = await api.input.to_http_response(kwargs, None)
        else:
            fake_resp = await api.input.to_http_response(inp, None)

        # TODO: Temporary workaround before moving everything to StreamingResponse
        if isinstance(fake_resp, starlette.responses.StreamingResponse):
            req_body = "".join([s async for s in fake_resp.body_iterator])
        else:
            req_body = fake_resp.body

        resp = await self.client.post(
            api.route,
            content=req_body,
            headers={"content-type": fake_resp.headers["content-type"]},
        )
        if resp.status_code != 200:
            raise BentoMLException(
                f"Error making request: {resp.status_code}: {str(await resp.aread())}"
            )

        fake_req = starlette.requests.Request(scope={"type": "http"})
        headers = starlette.datastructures.Headers(headers=resp.headers)
        fake_req._body = await resp.aread()
        # Request.headers sets a _headers variable. We will need to set this
        # value to our fake request object.
        fake_req._headers = headers  # type: ignore (request._headers is property)

        return await api.output.from_http_request(fake_req)

    async def close(self):
        await self.client.aclose()
        return await super().close()

class Client(ABC):
    server_url: str
    _svc: Service
    endpoints: list[str]

    _sync_client: SyncClient
    _async_client: AsyncClient

    def __init__(self, svc: Service, server_url: str):
        logger.warning(
            "Client is deprecated and will be removed in BentoML 2.0, please use AsyncClient or SyncClient instead."
        )
        self._svc = svc
        self.server_url = server_url

        if len(svc.apis) == 0:
            raise BentoMLException("No APIs were found when constructing client.")

        self.endpoints = []
        for name in self._svc.apis.keys():
            self.endpoints.append(name)

            if not hasattr(self, name):
                setattr(self, name, functools.partial(self.call, bentoml_api_name=name))

            if not hasattr(self, f"async_{name}"):
                setattr(
                    self,
                    f"async_{name}",
                    functools.partial(self.async_call, bentoml_api_name=name),
                )

    def call(
        self,
        bentoml_api_name: str,
        inp: t.Any = None,
        **kwargs: t.Any,
    ) -> t.Any:
        return self._sync_client.call(
            inp=inp, bentoml_api_name=bentoml_api_name, **kwargs
        )

    async def async_call(
        self, bentoml_api_name: str, inp: t.Any = None, **kwargs: t.Any
    ) -> t.Any:
        return await self._async_client.call(
            inp=inp, bentoml_api_name=bentoml_api_name, **kwargs
        )

    @staticmethod
    def wait_until_server_ready(
        host: str, port: int, timeout: float = 30, **kwargs: t.Any
    ) -> None:
        SyncClient.wait_until_server_ready(host, port, timeout, **kwargs)

    @staticmethod
    async def async_wait_until_server_ready(
        host: str, port: int, timeout: float = 30, **kwargs: t.Any
    ) -> None:
        await AsyncClient.wait_until_server_ready(host, port, timeout, **kwargs)

    @t.overload
    @staticmethod
    def from_url(server_url: str, *, kind: None | t.Literal["auto"] = ...) -> Client:
        ...

    @t.overload
    @staticmethod
    def from_url(server_url: str, *, kind: t.Literal["http"] = ...) -> HTTPClient:
        ...

    @t.overload
    @staticmethod
    def from_url(server_url: str, *, kind: t.Literal["grpc"] = ...) -> GrpcClient:
        ...

    @staticmethod
    def from_url(
        server_url: str,
        *,
        kind: t.Literal["auto", "http", "grpc"] | None = None,
        **kwargs: t.Any,
    ) -> Client:
        return SyncClient.from_url(server_url, kind=kind, **kwargs)

    def __enter__(self):
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc_value: BaseException | None,
        traceback: TracebackType | None,
    ) -> bool | None:
        return self._sync_client.close()

    async def __aenter__(self):
        return self

    async def __aexit__(
        self,
        exc_type: type[BaseException] | None,
        exc_value: BaseException | None,
        traceback: TracebackType | None,
    ) -> bool | None:
        return await self._async_client.close()

class AsyncClient(ABC):
    server_url: str
    _svc: Service
    endpoints: list[str]

    def __init__(self, svc: Service, server_url: str):
        self._svc = svc
        self.server_url = server_url

        if len(svc.apis) == 0:
            raise BentoMLException("No APIs were found when constructing client.")

        self.endpoints = []
        for name, api in self._svc.apis.items():
            self.endpoints.append(name)

            if not hasattr(self, name):
                setattr(
                    self,
                    name,
                    functools.partial(self._call, _bentoml_api=api),
                )

    async def call(
        self, bentoml_api_name: str, inp: t.Any = None, **kwargs: t.Any
    ) -> t.Any:
        return await self._call(
            inp, _bentoml_api=self._svc.apis[bentoml_api_name], **kwargs
        )

    @abstractmethod
    async def _call(
        self, inp: t.Any = None, *, _bentoml_api: InferenceAPI[t.Any], **kwargs: t.Any
    ) -> t.Any:
        raise NotImplementedError()

    async def close(self):
        pass

    async def __aenter__(self):
        return self

    async def __aexit__(
        self,
        exc_type: type[BaseException] | None,
        exc_value: BaseException | None,
        traceback: TracebackType | None,
    ) -> bool | None:
        await self.close()

    @staticmethod
    async def wait_until_server_ready(
        host: str, port: int, timeout: float = 30, **kwargs: t.Any
    ) -> None:
        try:
            from .http import AsyncHTTPClient

            await AsyncHTTPClient.wait_until_server_ready(host, port, timeout, **kwargs)
        except BadStatusLine:
            # when address is a RPC
            from .grpc import AsyncGrpcClient

            await AsyncGrpcClient.wait_until_server_ready(host, port, timeout, **kwargs)
        except Exception as err:
            # caught all other exceptions
            logger.error("Failed to connect to server %s:%s", host, port)
            logger.error(err)
            raise

    @t.overload
    @classmethod
    async def from_url(
        cls, server_url: str, *, kind: None | t.Literal["auto"] = ...
    ) -> AsyncGrpcClient | AsyncHTTPClient:
        ...

    @t.overload
    @classmethod
    async def from_url(
        cls, server_url: str, *, kind: t.Literal["http"] = ...
    ) -> AsyncHTTPClient:
        ...

    @t.overload
    @classmethod
    async def from_url(
        cls, server_url: str, *, kind: t.Literal["grpc"] = ...
    ) -> AsyncGrpcClient:
        ...

    @classmethod
    async def from_url(
        cls,
        server_url: str,
        *,
        kind: t.Literal["auto", "http", "grpc"] | None = None,
        **kwargs: t.Any,
    ) -> AsyncClient:
        if kind is None or kind == "auto":
            try:
                from .http import AsyncHTTPClient

                return await AsyncHTTPClient.from_url(server_url, **kwargs)
            except BadStatusLine:
                from .grpc import AsyncGrpcClient

                return await AsyncGrpcClient.from_url(server_url, **kwargs)
            except Exception as e:  # pylint: disable=broad-except
                raise BentoMLException(
                    f"Failed to create a BentoML client from given URL '{server_url}': {e} ({e.__class__.__name__})"
                ) from e
        elif kind == "http":
            from .http import AsyncHTTPClient

            return await AsyncHTTPClient.from_url(server_url, **kwargs)
        elif kind == "grpc":
            from .grpc import AsyncGrpcClient

            return await AsyncGrpcClient.from_url(server_url, **kwargs)
        else:
            raise BentoMLException(
                f"Invalid client kind '{kind}'. Must be one of 'http', 'grpc', or 'auto'."
            )

